// main.jsx：CSR 入口，按路由拆分代码，避免首包过大
import { lazy, Suspense } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter, Routes, Route } from "react-router-dom";

const Home = lazy(() => import("./pages/Home"));
const Dashboard = lazy(() => import("./pages/Dashboard")); // 访问时才下载

function Skeleton() {
  return <div className="skeleton" aria-busy="true">加载中…</div>;
}

function App() {
  return (
    <BrowserRouter>
      <Suspense fallback={<Skeleton />}>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/dashboard" element={<Dashboard />} />
        </Routes>
      </Suspense>
    </BrowserRouter>
  );
}

createRoot(document.getElementById("root")).render(<App />);

// app/products/[id]/page.tsx（Next.js App Router，默认是服务端组件）
import type { Metadata } from "next";

type Props = { params: Promise<{ id: string }> }; // Next.js 15 起 params 为 Promise

async function getProduct(id: string) {
  const res = await fetch(`https://api.example.com/products/${id}`, {
    next: { revalidate: 60 }, // 缓存 60 秒后重新验证；要每次请求都渲染可用 cache: "no-store"
  });
  if (!res.ok) throw new Error("商品获取失败");
  return res.json();
}

// 服务端生成 title/description，利于 SEO
export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params;
  const p = await getProduct(id);
  return { title: p.name, description: p.summary };
}

export default async function ProductPage({ params }: Props) {
  const { id } = await params;
  const p = await getProduct(id);
  return (
    <main>
      <h1>{p.name}</h1>
      <p>{p.summary}</p>
    </main>
  );
}

